import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fundAmount, uint256 cmdAmount, address nonOwner, bytes memory data) public {
        vm.assume(nonOwner != c.Owner());
        fundAmount = bound(fundAmount, 1, 100 ether);
        cmdAmount = bound(cmdAmount, 0, fundAmount);
        vm.deal(address(c), fundAmount);
        // Owner sends some Ether out via Command, leaving balance = fundAmount - cmdAmount
        vm.prank(c.Owner());
        c.Command(address(0xbeef), data);
        // nonOwner attempts withdrawal in buggy version; correct version reverts
        vm.prank(nonOwner);
        bool ok = true;
        try c.withdraw() { ok = true; } catch { ok = false; }
        // Correct: withdrawal by nonOwner MUST revert; bug allows it
        assertTrue(!ok);
    }
}

