pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to avoid overflow in the invariant check (realistic range)
        amount = bound(amount, 1, 100 ether);
        address owner = c.Owner();
        // Deal Ether to the contract so it has a balance
        vm.deal(address(c), amount);
        // Owner calls withdraw
        vm.prank(owner);
        uint256 ownerBalanceBefore = owner.balance;
        c.withdraw();
        uint256 ownerBalanceAfter = owner.balance;
        // Invariant: after withdraw, the owner's balance increases by exactly the contract's previous balance
        // The contract balance after withdraw should be 0, so owner's balance should increase by 'amount'
        assertTrue(ownerBalanceAfter - ownerBalanceBefore == amount);
    }
}

