pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint96 donateAmount, uint96 fuzzSeed) public {
        // donateAmount: Ether initially sent into the contract
        // fuzzSeed: used to derive a distinct owner address (the fuzzer supplies the seed)
        vm.assume(donateAmount > 0);
        address owner = address(uint160(fuzzSeed) | uint160(0x1)); // ensure non‑zero address, distinct from default deployer
        vm.assume(owner != address(this) && owner != address(0));

        // deploy a fresh contract with a known Owner that equals the derived owner
        vm.prank(owner);
        c = new C();

        // fund the contract
        vm.deal(address(this), donateAmount);
        (bool funded,) = address(c).call{value: donateAmount}("");
        require(funded, "funding failed");

        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;

        // Owner performs the withdrawal
        vm.prank(owner);
        c.withdraw();

        uint256 ownerBalanceAfter = owner.balance;
        // The rule: owner's balance increase == contract's balance before the withdrawal
        // (the bug pays zero, so the increase is zero while contractBalanceBefore > 0)
        assertTrue(ownerBalanceAfter - ownerBalanceBefore == contractBalanceBefore);
    }
}

