pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 initial, uint96 extra) public {
        // Restrict initial balance to a reasonable range to avoid overflow in funding
        vm.assume(initial > 0 && initial <= type(uint96).max);
        // extra is any amount sent after setup, before withdrawal
        vm.assume(extra <= type(uint96).max);

        address owner = c.Owner();
        // Fund the contract with initial Ether from someone else
        vm.deal(address(this), initial);
        (bool s,) = address(c).call{value: initial}("");
        require(s, "funding failed");

        uint256 balance_before = address(c).balance;
        require(balance_before >= initial, "unexpected balance");

        // Owner sends extra Ether to the contract (e.g. via multiplicate or receive)
        vm.deal(owner, extra);
        vm.prank(owner);
        (bool ok,) = address(c).call{value: extra}("");
        require(ok, "extra funding failed");

        uint256 final_balance_before_withdraw = address(c).balance;
        require(final_balance_before_withdraw == balance_before + extra, "balance miscount");

        // Owner withdraws
        vm.prank(owner);
        c.withdraw();

        uint256 balance_after = address(c).balance;
        // General rule: after a withdraw call by the owner, the contract's balance must be strictly less than before.
        // The buggy version transfers 0, so balance_after == final_balance_before_withdraw, violating this.
        assertTrue(balance_after < final_balance_before_withdraw, "balance did not decrease after withdraw");
    }
}

