pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amountToSend, uint256 initialContractEth) public {
        // Bound initialContractEth so vm.deal doesn't overflow; keep domain wide
        initialContractEth = bound(initialContractEth, 0, 1e30);
        amountToSend = bound(amountToSend, 0, 1e30);

        // Fund contract with initialContractEth
        vm.deal(address(c), initialContractEth);
        uint256 preBalance = address(c).balance;

        // Owner sends amountToSend via Command to their own address (no adversarial counterparty needed)
        address owner = c.Owner();
        vm.deal(owner, amountToSend);
        vm.prank(owner);
        c.Command(owner, hex"");

        uint256 postBalance = address(c).balance;
        // Reference: balance after Command should be preBalance + amountToSend
        // Mutant: transfers all balance to Owner, making postBalance 0, which breaks the rule
        assertTrue(postBalance == preBalance + amountToSend);
    }
}
